                  "বনে থাকে বাঘ। গাছে থাকে পাখি। জলে থাকে মাছ। ডালে আছে ফল। পাখি ফল খায়। পাখা মেলে ওড়ে। বাঘ আছে আম-বনে। গায়ে চাকা চাকা দাগ। পাখি বনে গান গায়। মাছ জলে খেলা করে।",
