                  "রাজধানী ঢাকায় আধুনিক মেট্রোরেল ও এলিভেটেড এক্সপ্রেসওয়ে চালু হওয়ার ফলে নগর পরিবহনে গতিশীলতা এসেছে এবং যানজট অনেকটাই লাঘব হয়েছে। যোগাযোগ ব্যবস্থার আধুনিকায়ন কর্মঘণ্টা বাঁচিয়ে দেশের সামগ্রিক অর্থনৈতিক প্রবৃদ্ধিতে গতি সঞ্চার করছে।",
                  "স্মার্ট গভর্নেন্স ব্যবস্থার মূল লক্ষ্য হলো সরকারি সেবা সরাসরি ও ঝামেলাহীনভাবে প্রতিটি নাগরিকের নাগালে পৌঁছে দেওয়া। ন্যাশনাল আইডি, ই-পাসপোর্ট, অনলাইন ড্রাইভিং লাইসেন্স এবং ডিজিটাল ট্যাক্স রিটার্ন জমা দেওয়া আজ ঘরে বসেই নির্বিঘ্নে সম্পন্ন করা সম্ভব হচ্ছে।",
                  "প্রতিটি মানুষের জন্মগত অধিকার হলো তার মৌলিক স্বাধীনতা ও মানবিক মর্যাদা নিয়ে বেঁচে থাকা। সামাজিক বৈষম্য, শোষণ এবং নিপীড়নের বিরুদ্ধে রুখে দাঁড়িয়ে একটি অন্তর্ভুক্তিমূলক ও মানবিক সমাজ গড়ে তোলাই আধুনিক সভ্যতার মূল লক্ষ্য।",
